import test from 'node:test';
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { createPool,transaction } from '../src/db/pool.js';
import { migrate } from '../src/db/migrate.js';
import { bootstrap } from '../src/modules/bootstrap.service.js';
import { createApp } from '../src/app.js';
import { readConfig } from '../src/config.js';
import { hashPassword,verifyPassword } from '../src/modules/auth.service.js';
import { moduleAccess,OPTIONAL_MODULES } from '../src/modules/registry.js';
import { createProductLine } from '../../shared/catalog.js';

test('configuration rejects restaurant DB and production foundation',()=>{
  assert.throws(()=>readConfig({DATABASE_URL:'postgresql://localhost/restaurant'}));
  assert.throws(()=>readConfig({DATABASE_URL:'postgresql://localhost/sham_touch_retail_dev',NODE_ENV:'production'}));
});
test('passwords use salted scrypt and verify safely',async()=>{
  const first=await hashPassword('Test-only-long-password!'),second=await hashPassword('Test-only-long-password!');
  assert.notEqual(first,second);assert.equal(await verifyPassword('Test-only-long-password!',first),true);assert.equal(await verifyPassword('incorrect',first),false);
});
test('module policy fails closed for expiry, wrong product, absent entitlement/settings/permissions',()=>{
  for(const id of OPTIONAL_MODULES){const license={status:'ACTIVE',activated:true,product:'retail',features:{[id]:true}};assert.equal(moduleAccess(id,license,true,[`modules.${id}`]),true);for(const status of ['EXPIRED','NOT_CONFIGURED','CLOCK_ROLLBACK','DEVICE_MISMATCH'])assert.equal(moduleAccess(id,{...license,status},true,[`modules.${id}`]),false);assert.equal(moduleAccess(id,{...license,product:'restaurant'},true,[`modules.${id}`]),false);assert.equal(moduleAccess(id,license,false,[`modules.${id}`]),false);assert.equal(moduleAccess(id,license,true,[]),false);}
});
test('variant unit prices override calculated defaults',()=>{
  const product={id:'matrix',name:'Shirt',price:10,stock:0,units:[{id:'base',name:'piece',factor:1,price:10,sell:true,purchase:true},{id:'box',name:'box',factor:5,price:40,sell:true,purchase:true}],variants:[{id:'red',values:{color:'red'},price:12,stock:0,unitPrices:{box:49}}]};
  assert.equal(createProductLine(product,{variantId:'red',unitId:'box'}).price,49);delete product.variants[0].unitPrices;assert.equal(createProductLine(product,{variantId:'red',unitId:'box'}).price,60);
});

test('PostgreSQL integration (requires explicit dedicated *_test database)',async t=>{
  const connection=process.env.TEST_DATABASE_URL;
  assert.ok(connection,'Set TEST_DATABASE_URL to an isolated sham_touch_retail_*_test PostgreSQL database; integration tests never silently skip');
  const url=new URL(connection);assert.match(url.pathname,/^\/sham_touch_retail_[a-z0-9_]*test$/i);
  const admin=createPool(connection),schema=`phase2_${randomUUID().replaceAll('-','')}`;
  await admin.query(`CREATE SCHEMA ${schema}`);await admin.end();
  url.searchParams.set('options',`-c search_path=${schema}`);
  const pool=createPool(url.href);
  let server;
  try{
    await t.test('migrations apply transactionally and are tracked/idempotent',async()=>{assert.equal((await migrate(pool)).length,9);assert.deepEqual(await migrate(pool),[]);});
    const fixture=await bootstrap(pool,{company:'Synthetic Retail Test',username:`admin_${schema}`,password:'Synthetic-Admin-Password!'});
    await t.test('bootstrap cannot overwrite an existing business',async()=>{await assert.rejects(bootstrap(pool,{company:'Other',username:'otheradmin',password:'Another-Long-Password!'}));});
    const config={origin:'http://127.0.0.1:5188',sessionHours:8,secureCookie:false};
    const app=createApp({pool,config,logger:()=>{}});server=app.listen(0,'127.0.0.1');await new Promise(resolve=>server.once('listening',resolve));
    const base=`http://127.0.0.1:${server.address().port}/api`;
    let cookie,csrf,user;
    async function request(path,{method='GET',body,session=cookie,csrfToken=csrf,key,origin}={}){
      const headers={};if(body!==undefined)headers['Content-Type']='application/json';if(session)headers.Cookie=session;if(csrfToken)headers['X-CSRF-Token']=csrfToken;if(key)headers['Idempotency-Key']=key;if(origin)headers.Origin=origin;
      const response=await fetch(base+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body)});return {status:response.status,data:await response.json(),cookie:response.headers.get('set-cookie')};
    }
    async function newProduct(extra={}){const id=randomUUID();const body={id,name:`Product ${id}`,barcode:id,unit:'piece',price:10,costPrice:2,stock:0,...extra};const response=await request('/products',{method:'POST',body});assert.equal(response.status,201,JSON.stringify(response.data));return response.data;}
    const movement=(product,extra={})=>({productId:product.id,warehouseId:fixture.warehouseId,unitId:'base',quantity:10,unitCost:2,kind:'opening',reference:randomUUID(),...extra});
    const post=(body,key=randomUUID())=>request('/stock/movements',{method:'POST',body,key});
    await t.test('all business APIs require authentication',async()=>{for(const path of ['/products','/users','/roles','/modules','/stock/ledger','/audit','/organization'])assert.equal((await request(path,{session:null})).status,401);});
    await t.test('invalid credentials and login validation are rejected',async()=>{assert.equal((await request('/auth/login',{method:'POST',body:{username:'unknown',password:'no'}})).status,401);assert.equal((await request('/auth/login',{method:'POST',body:{username:'x',password:'x',admin:true}})).status,400);});
    await t.test('login uses HttpOnly SameSite cookie; session restores identity',async()=>{const response=await request('/auth/login',{method:'POST',body:{username:`admin_${schema}`,password:'Synthetic-Admin-Password!'}});assert.equal(response.status,200);assert.match(response.cookie,/HttpOnly/);assert.match(response.cookie,/SameSite=Strict/);cookie=response.cookie.split(';')[0];csrf=response.data.csrfToken;user=response.data.user;assert.equal((await request('/auth/me')).data.user.id,fixture.userId);});
    await t.test('write CSRF and cross-origin requests are rejected',async()=>{assert.equal((await request('/products',{method:'POST',body:{},csrfToken:'wrong'})).status,403);assert.equal((await request('/auth/me',{origin:'https://untrusted.example'})).status,403);});
    let product;
    await t.test('product create preserves legacy ids and arbitrary metadata',async()=>{product=await newProduct({id:123,barcode:'legacy-123',custom:{retain:['original']},color:'bg-blue-50'});assert.equal(product.id,123);assert.deepEqual(product.custom,{retain:['original']});assert.equal(product.stock,0);});
    await t.test('product search and pagination run on server, with strict limits',async()=>{const result=await request('/products?q=legacy-123&limit=1');assert.equal(result.status,200);assert.equal(result.data.total,1);assert.equal(result.data.items[0].id,123);assert.equal((await request('/products?limit=1000')).status,400);assert.equal((await request('/products?sort=;DROP')).status,400);});
    await t.test('thousands of products return only a bounded server page',async()=>{
      await transaction(pool,async db=>{
        await db.query(`INSERT INTO products(company_id,id,name,type,currency,data) SELECT $1,'bulk-'||n,'Bulk synthetic '||n,'stock','SAR',jsonb_build_object('id','bulk-'||n,'name','Bulk synthetic '||n,'type','stock','price',1,'stock',0,'costPrice',0,'unit','piece','baseUnitId','base','units',jsonb_build_array(jsonb_build_object('id','base','name','piece','factor',1,'price',1,'barcode','','sell',true,'purchase',true)),'variants','[]'::jsonb,'attributes','[]'::jsonb) FROM generate_series(1,1500) n`,[fixture.companyId]);
        await db.query("INSERT INTO product_units SELECT company_id,id,'base','piece',1,1,true,true,true FROM products WHERE company_id=$1 AND id LIKE 'bulk-%'",[fixture.companyId]);
        await db.query("INSERT INTO product_variants SELECT company_id,id,'',NULL,'{}'::jsonb,1 FROM products WHERE company_id=$1 AND id LIKE 'bulk-%'",[fixture.companyId]);
      });
      const response=await request('/products?q=Bulk%20synthetic&page=2&limit=50');assert.equal(response.status,200);assert.equal(response.data.total,1500);assert.equal(response.data.items.length,50);assert.equal(response.data.page,2);
    });
    await t.test('duplicate barcode across products/units is rejected by transaction',async()=>{const result=await request('/products',{method:'POST',body:{id:'duplicate',name:'dup',barcode:'legacy-123',price:1,stock:0}});assert.equal(result.status,409);assert.equal((await request('/products/duplicate')).status,404);});
    await t.test('updates require version and preserve metadata; stale edit rejected',async()=>{const result=await request('/products/123',{method:'PUT',body:{...product,name:'Updated'}});assert.equal(result.status,200);assert.deepEqual(result.data.custom,product.custom);assert.equal((await request('/products/123',{method:'PUT',body:product})).status,409);product=result.data;});
    await t.test('direct balance edits and opening stock in CRUD are prohibited',async()=>{assert.equal((await request('/products/123',{method:'PUT',body:{...product,stock:10}})).status,409);assert.equal((await request('/products',{method:'POST',body:{id:'badstock',name:'Bad',price:1,stock:5}})).status,409);});
    await t.test('receipt ledger and weighted average cost use database numeric arithmetic',async()=>{assert.equal((await post(movement(product))).status,201);const received=await post(movement(product,{kind:'receipt',unitCost:4}));assert.equal(received.status,201);assert.equal(Number(received.data.balance_after),20);assert.equal(Number(received.data.average_cost_after),3);const issue=await post(movement(product,{kind:'issue',quantity:-1,unitCost:999}));assert.equal(Number(issue.data.unit_cost),3);assert.equal(Number(issue.data.balance_after),19);});
    await t.test('ledger and audit history are immutable and balances cannot be edited directly',async()=>{await assert.rejects(pool.query('UPDATE stock_balances SET quantity=100 WHERE company_id=$1',[fixture.companyId]));await assert.rejects(pool.query('UPDATE stock_ledger SET reference=reference WHERE company_id=$1',[fixture.companyId]));await assert.rejects(pool.query('DELETE FROM audit_logs WHERE company_id=$1',[fixture.companyId]));});
    await t.test('idempotent stock replay returns same movement; changed body is conflict',async()=>{const body=movement(product,{kind:'receipt',quantity:1}),key=randomUUID();const first=await post(body,key),second=await post(body,key);assert.equal(first.status,201);assert.equal(first.data.id,second.data.id);assert.equal((await post({...body,quantity:2},key)).status,409);});
    await t.test('services and non-stock never post inventory movements',async()=>{for(const type of ['service','nonStock']){const item=await newProduct({type});assert.equal((await post(movement(item))).status,422);assert.equal((await request(`/products/${item.id}`)).data.stock,0);}});
    await t.test('invalid API movement input and missing idempotency key are rejected',async()=>{assert.equal((await request('/stock/movements',{method:'POST',body:movement(product)})).status,400);assert.equal((await post(movement(product,{quantity:0}))).status,400);assert.equal((await post({...movement(product),unitFactor:999})).status,400);});
    await t.test('fractional quantity policy is enforced, including at SQL boundary',async()=>{assert.equal((await post(movement(product,{quantity:0.5}))).status,422);const weighted=await newProduct({allowFractional:true});const result=await post(movement(weighted,{quantity:0.125}));assert.equal(result.status,201);assert.equal(Number(result.data.balance_after),0.125);});
    await t.test('multi-UOM snapshots original factor and normalizes unit cost',async()=>{const item=await newProduct({barcode:'',units:[{id:'base',name:'piece',factor:1,price:10,barcode:'',sell:true,purchase:true},{id:'box',name:'carton',factor:24,price:200,barcode:randomUUID(),sell:true,purchase:true}]});const result=await post(movement(item,{unitId:'box',quantity:5,unitCost:48}));assert.equal(result.status,201);assert.equal(Number(result.data.balance_after),120);assert.equal(Number(result.data.unit_factor),24);assert.equal(Number(result.data.unit_cost),2);});
    await t.test('variants retain independent price matrices, barcodes and stock',async()=>{const item=await newProduct({barcode:'',attributes:[{name:'Color',values:['Red','Blue']}],variants:[{id:'red',sku:randomUUID(),barcode:randomUUID(),values:{Color:'Red'},price:12,stock:0,unitPrices:{base:11}},{id:'blue',sku:randomUUID(),barcode:randomUUID(),values:{Color:'Blue'},price:13,stock:0}]});assert.equal((await post(movement(item,{variantId:'red'}))).status,201);const current=(await request(`/products/${item.id}`)).data;assert.equal(current.variants[0].stock,10);assert.equal(current.variants[1].stock,0);assert.equal(current.variants[0].unitPrices.base,11);assert.equal((await post(movement(item))).status,422);});
    await t.test('concurrent cashiers cannot both consume the same remaining stock',async()=>{const item=await newProduct();assert.equal((await post(movement(item))).status,201);const results=await Promise.all([post(movement(item,{kind:'issue',quantity:-7})),post(movement(item,{kind:'issue',quantity:-7}))]);assert.deepEqual(results.map(result=>result.status).sort(),[201,422]);assert.equal((await request(`/products/${item.id}`)).data.stock,3);});
    await t.test('failed operation rolls back ledger, balance and idempotency atomically',async()=>{const item=await newProduct(),key=randomUUID(),body=movement(item,{kind:'issue',quantity:-100});assert.equal((await post(body,key)).status,422);assert.equal(Number((await pool.query('SELECT count(*) FROM idempotency_requests WHERE company_id=$1 AND key=$2',[fixture.companyId,key])).rows[0].count),0);assert.equal(Number((await pool.query('SELECT count(*) FROM stock_balances WHERE company_id=$1 AND product_id=$2',[fixture.companyId,String(item.id)])).rows[0].count),0);});
    await t.test('separate warehouses keep distinct balances and scope is enforced',async()=>{const warehouse=await request('/organization/warehouses',{method:'POST',body:{branchId:fixture.branchId,name:'Warehouse 2'}});assert.equal(warehouse.status,201);assert.equal((await request(`/products/123?warehouseId=${warehouse.data.id}`)).status,200,'scope changes are refreshed on every request');const again=await request(`/products/123?warehouseId=${warehouse.data.id}`);assert.equal(again.status,200);assert.equal(again.data.stock,0);assert.equal((await request(`/products/123?warehouseId=${randomUUID()}`)).status,403);});
    await t.test('currency and inclusive/exclusive tax configuration persist',async()=>{assert.equal((await request('/organization/currencies',{method:'PUT',body:{code:'USD',rate:3.75,decimals:2}})).status,200);assert.equal((await request('/organization/taxes',{method:'PUT',body:{id:'VAT',name:'VAT',rate:15,priceIncludesTax:true}})).status,200);const item=await newProduct({currency:'USD',taxId:'VAT',priceIncludesTax:true});assert.equal(item.taxId,'VAT');assert.equal(item.currency,'USD');});
    await t.test('cashier has read access but cannot modify catalog or view audit/users',async()=>{const body={username:`cash_${schema}`,name:'Cashier',password:'Synthetic-Cashier-Password!',roleIds:[fixture.roleIds.Cashier],branches:[fixture.branchId],warehouses:[fixture.warehouseId]};assert.equal((await request('/users',{method:'POST',body})).status,200);const signed=await request('/auth/login',{method:'POST',body:{username:body.username,password:body.password}});const session=signed.cookie.split(';')[0],csrfToken=signed.data.csrfToken;assert.equal((await request('/products',{session})).status,200);for(const path of ['/users','/audit'])assert.equal((await request(path,{session})).status,403);assert.equal((await request('/products',{method:'POST',body:{},session,csrfToken})).status,403);});
    await t.test('custom roles cannot grant more than actor holds',async()=>{const response=await request('/roles',{method:'POST',body:{name:'Delegated manager',permissions:['catalog.read','roles.manage']}});assert.equal(response.status,200);const body={username:`delegate_${schema}`,name:'Delegate',password:'Synthetic-Delegate-Password!',roleIds:[response.data.id],branches:[fixture.branchId],warehouses:[fixture.warehouseId]};await request('/users',{method:'POST',body});const signed=await request('/auth/login',{method:'POST',body:{username:body.username,password:body.password}});assert.equal((await request('/roles',{method:'POST',body:{name:'Escalation',permissions:['users.manage']},session:signed.cookie.split(';')[0],csrfToken:signed.data.csrfToken})).status,403);});
    await t.test('last active Admin and built-in Admin permissions are protected',async()=>{assert.equal((await request(`/users/${fixture.userId}`,{method:'PUT',body:{username:user.username,name:user.name,active:false,roleIds:[fixture.roleIds.Admin],branches:[fixture.branchId],warehouses:[fixture.warehouseId]}})).status,409);assert.equal((await request('/auth/me')).status,200);assert.equal((await request(`/roles/${fixture.roleIds.Admin}`,{method:'PUT',body:{name:'Admin',permissions:[]}})).status,409);});
    await t.test('optional modules cannot be enabled by mutable settings or restaurant license',async()=>{assert.equal((await request('/modules/advancedInventory',{method:'PUT',body:{enabled:true}})).status,200);const result=await request('/modules');assert.equal(result.data.license.status,'NOT_CONFIGURED');assert.equal(result.data.items.find(item=>item.id==='advancedInventory').available,false);assert.equal((await request('/modules/advancedInventory/access')).status,403);assert.equal((await request('/modules/notAFeature/access')).status,400);});
    await t.test('caller cannot inject trusted license features into mutable module settings',async()=>{assert.equal((await request('/modules/advancedInventory',{method:'PUT',body:{enabled:true,features:{advancedInventory:true},status:'ACTIVE'}})).status,400);});
    const legacyImport={products:[{id:'import-a',name:'Legacy import',price:4,costPrice:2,stock:10,barcode:'import-a-bar',color:'retained',unknown:{legacy:true}},{id:'import-service',name:'Repair',type:'service',price:10,stock:0,barcode:''}],warehouseId:fixture.warehouseId};
    await t.test('import preview is read-only and reports errors without overwriting',async()=>{const original=structuredClone(legacyImport);assert.equal((await request('/imports/preview',{method:'POST',body:legacyImport})).data.valid,true);assert.equal((await request('/products/import-a')).status,404);assert.deepEqual(legacyImport,original);const invalid=await request('/imports/preview',{method:'POST',body:{...legacyImport,products:[...legacyImport.products,legacyImport.products[0]]}});assert.equal(invalid.data.valid,false);assert.equal(invalid.data.errors.length,1);});
    await t.test('import commit is atomic and replay is idempotent',async()=>{const first=await request('/imports/commit',{method:'POST',body:legacyImport}),second=await request('/imports/commit',{method:'POST',body:legacyImport});assert.equal(first.status,201);assert.equal(first.data.imported,2);assert.equal(second.data.id,first.data.id);assert.equal(second.data.replayed,true);const item=(await request('/products/import-a')).data;assert.equal(item.stock,10);assert.deepEqual(item.unknown,{legacy:true});assert.equal(Number((await pool.query('SELECT count(*) FROM stock_ledger WHERE product_id=$1',['import-a'])).rows[0].count),1);});
    await t.test('failed import preserves source and rolls back all product writes',async()=>{const bad={...legacyImport,products:[{id:'rollback-good',name:'Good',price:1,stock:0},{id:'rollback-bad',name:'Bad currency',price:1,stock:0,currency:'ZZZ'}]};const original=structuredClone(bad);assert.equal((await request('/imports/commit',{method:'POST',body:bad})).status,422);assert.equal((await request('/products/rollback-good')).status,404);assert.deepEqual(bad,original);});
    await t.test('stock and audit APIs are paginated and include movement references',async()=>{const ledger=await request('/stock/ledger?limit=2');assert.equal(ledger.status,200);assert.equal(ledger.data.items.length,2);assert.ok(ledger.data.total>2);assert.ok(ledger.data.items[0].reference);const logs=await request('/audit?limit=2');assert.equal(logs.status,200);assert.equal(logs.data.items.length,2);});
    await t.test('archiving is soft and preserves rows and history',async()=>{const item=await newProduct();assert.equal((await request(`/products/${item.id}`,{method:'DELETE'})).status,200);assert.equal((await request(`/products/${item.id}`)).status,404);assert.equal((await pool.query('SELECT 1 FROM products WHERE company_id=$1 AND id=$2 AND archived_at IS NOT NULL',[fixture.companyId,String(item.id)])).rowCount,1);});
    await t.test('generic transaction helper rolls back writes',async()=>{await assert.rejects(transaction(pool,async db=>{await db.query("INSERT INTO categories VALUES($1,'rollback-category','Temporary')",[fixture.companyId]);throw new Error('synthetic failure');}));assert.equal((await pool.query("SELECT 1 FROM categories WHERE company_id=$1 AND id='rollback-category'",[fixture.companyId])).rowCount,0);});
    await t.test('logout revokes session',async()=>{assert.equal((await request('/auth/logout',{method:'POST',body:{}})).status,200);assert.equal((await request('/auth/me')).status,401);});
  }finally{if(server)await new Promise(resolve=>server.close(resolve));await pool.end();}
});
